#!/usr/bin/env python3
"""Concise Russian report with values read from immutable experiment outputs."""
import json
from pathlib import Path
import pandas as pd
OUT=Path(__file__).resolve().parent
DEV='development_2023_2025';JAN='jan2026_retrospective';MAR='march2026_retrospective'
NAMES={'v3_long':'V3 long, без Chronos','synth_no_oxr':'Synth, без OXR','synth_basis2018_D2':'Synth + OXR basis с2018, D+2','synth_basis2010_D2':'Synth + OXR basis с2010, D+2','synth_full2010_D2':'Synth + OXR full с2010, D+2','synth_basis2010_D3':'Synth + OXR basis с2010, D+3','synth_full2010_D3':'Synth + OXR full с2010, D+3','synth_availability2010_D2':'Synth + только наличие/возраст OXR','small_no_oxr':'Small FT300, без OXR','small_basis2010_D2':'Small FT300 + OXR basis с2010','synth_kzt_no_oxr':'Ни OXR, ни Halyk','synth_kzt_basis2010_D2':'Только OXR, D+2','synth_kzt_halyk_D2':'Только Halyk, D+2','synth_kzt_basis2010_halyk_D2':'OXR + Halyk, оба D+2','synth_kzt_halyk_D1':'Только Halyk, D+1','synth_kzt_basis2010_halyk_H1O2':'OXR D+2 + Halyk D+1','synth_kzt_halyk_D3':'Только Halyk, D+3','synth_kzt_basis2010_halyk_D3':'OXR + Halyk, оба D+3'}
def table(head,rows):return '\n'.join(['| '+' | '.join(head)+' |','|'+'|'.join(['---']*len(head))+'|',*['| '+' | '.join(map(str,row))+' |' for row in rows]])
def get(df,cid,stage,scope):return df[df.config_id.eq(cid)&df.stage.eq(stage)&df.scope.eq(scope)].iloc[0]
def delta(df,cid,baseline,stage=DEV,scope='all'):
    r=df[df.config_id.eq(cid)&df.benchmark.eq(baseline)&df.stage.eq(stage)&df.scope.eq(scope)].iloc[0]
    return f'{r.delta_brier:+.6f} [{r.delta_brier_ci95_low:+.6f}; {r.delta_brier_ci95_high:+.6f}]'
def main():
    metrics=pd.read_csv(OUT/'summary.csv');ci=pd.read_csv(OUT/'paired_intervals.csv')
    rows=[]
    for cid in ['v3_long','synth_no_oxr','synth_basis2018_D2','synth_basis2010_D2','synth_full2010_D2','synth_basis2010_D3','synth_full2010_D3','small_no_oxr','small_basis2010_D2']:
        a,b,c=(get(metrics,cid,stage,'all') for stage in [DEV,JAN,MAR])
        rows.append([NAMES[cid],f'{a.brier:.6f}',f'{b.brier:.6f}',f'{c.brier:.6f}',f'{a.forward_delta_bps:.2f}',f'{b.forward_delta_bps:.2f}'])
    main_table=table(['Модель','Brier 2023–25 ↓','Brier, январь2026 ↓','Brier, март2026 ↓','Эффект сигналов 2023–25, б.п.','Эффект, январь2026, б.п.'],rows)
    rows=[]
    for cid in ['synth_kzt_no_oxr','synth_kzt_basis2010_D2','synth_kzt_halyk_D2','synth_kzt_basis2010_halyk_D2','synth_kzt_halyk_D1','synth_kzt_basis2010_halyk_H1O2','synth_kzt_halyk_D3','synth_kzt_basis2010_halyk_D3']:
        a,b,c=(get(metrics,cid,stage,'KZT') for stage in [DEV,JAN,MAR])
        rows.append([NAMES[cid],f'{a.brier:.6f}',f'{b.brier:.6f}',f'{c.brier:.6f}',f'{a.forward_delta_bps:.2f}',f'{b.forward_delta_bps:.2f}'])
    bank_table=table(['KZT, локальная калибровка','Brier 2023–25','Brier, январь2026','Brier, март2026','Эффект 2023–25, б.п.','Эффект, январь2026, б.п.'],rows)
    data=json.loads((OUT/'input_receipt.json').read_text());selection=json.loads((OUT/'selection.json').read_text())
    text=f'''# Chronos + OXR 2010–2026 и банковские признаки

Расширение истории OXR до 2010 года не дало сильного дополнительного выигрыша десятилетней голове Chronos. В заранее выбранном варианте исследовательский Brier немного улучшился, но интервалы включают ноль, а в 2026 году улучшение не сохранилось. Для KZT полезнее оказался однодневный исторический сигнал Halyk; его эффект заметно зависит от предполагаемой задержки доступности. Добавление OXR к Halyk не улучшило исследовательский Brier.

Реально обучены **85 голов HGB: 17 вариантов на трёх исследовательских годах и двух заморозках 2026 года**. Новых обучений нейросетей и новых нейросетевых прогнозов нет: использованы неизменённые веса и квантили из прежнего эксперимента. [Протокол](protocol.json) и [дополнение с однодневным лагом Halyk](protocol_addendum_halyk_lag1.json) зафиксированы до первого обучения. [Выбор по исследовательским данным](selection.json) сохранён до новых прогнозов 2026 года.

**Данные и постановка.** Один общий снимок OXR содержит {data['snapshot_rows']:,} строк с {data['snapshot_min_date']} по {data['snapshot_max_date']}. Контроль с2018 года получен усечением этого же файла с17июня2018 года; версия поставщика не меняется между вариантами. Обучение головы использует десять лет перед годом калибровки, точные базовые признаки V3 и14 прежних сводок Chronos. Поэтому первое окно начинается в2012 году: отсутствующие до2012 года нейросетевые прогнозы не подставлялись в обучение.

Метка остаётся исходной меткой NOW на курсах ЦБ: текущая стоимость валюты в рублях не выше минимума следующих пяти эффективных наблюдений, включая равенство. Это **не прогноз целевой банковской котировки**. Банковские ряды здесь служат признаками. Для Halyk архив содержит сторону BANK SELL RUB — банк продаёт рубли; это не цена исполнения перевода RUB→KZT для клиента.

OXR считается доступным в более поздний из моментов «указанная публикация» и «завершение дня наблюдения», плюс24часа в основном варианте и48часов в проверке чувствительности. При ежедневных наблюдениях это D+2 иD+3 календарных дня. Решение принимается в10:05 по Москве; допустимая давность источника — семь дней. Halyk присоединяется по дате действия плюс один, два или три календарных дня. **Для каждого лага голова обучена отдельно: это сравнение моделей с разной доступностью данных, а не имитация внезапного сбоя уже развёрнутой модели.**

Последние пять наблюдений каждой валюты удалены из обучения и калибровки, реальные даты созревания меток проверены. Пороги, калибровка и начальное состояние пауз между сигналами используют только прошлую историю. У всех голов одинаковые параметры HGB:120 итераций, глубина2, без ранней остановки. Основной Synth не дообучался; Small FT300 включён заранее как дополнительный контроль. Веса опубликованы после начала исследовательских лет, поэтому сравнение ретроспективное. Для Small ранние обучающие признаки головы также не являются независимыми прогнозами нейросети: фиксированные веса дообучались на этой ранней истории.

**Все пять валют.** Чем меньше Brier, тем точнее вероятности. Эффект сигналов — превышение среднего исходного forward-показателя над равномерным случайным днём внутри той же ячейки «год × валюта», с весами по фактическим сигналам. Его нельзя интерпретировать как банковскую экономию после спреда и комиссий.

{main_table}

По заранее заданному правилу минимум исследовательского Brier среди noOXR, basis2010 иfull2010 выбрал `{selection['choices']['all']['selected']}`. Его разница с Synth без OXR составила {delta(ci,'synth_basis2010_D2','synth_no_oxr')}. Эффект сигналов при этом снизился с41.90 до38.05б.п. На январской заморозке разница Brier равна {delta(ci,'synth_basis2010_D2','synth_no_oxr',JAN)}; на мартовской — {delta(ci,'synth_basis2010_D2','synth_no_oxr',MAR)}.

Чистое сравнение истории с2010 против истории с2018 года даёт исследовательскую разницу {delta(ci,'synth_basis2010_D2','synth_basis2018_D2')}. Дополнительные ранние данные не дали заметного прироста этой модели. Отрицательный результат полной группы OXR и контроль только наличия/возраста источника также сохранены в [полной таблице](summary.csv).

**Казахстан и Halyk.** Здесь HGB обучается на всех пяти валютах, а калибровка, пороги, история сигналов и оценка относятся только кKZT. Контроли «без источников», «только OXR», «только Halyk» и «оба источника» отделяют вклад банковских признаков от локальной калибровки.

{bank_table}

Консервативный выбор по исследовательским данным — `{selection['choices']['KZT']['selected']}`. Варианты Halyk D+1 не участвовали в этом выборе. Для Halyk D+1 против локального Synth без внешних данных разница Brier равна {delta(ci,'synth_kzt_halyk_D1','synth_kzt_no_oxr',DEV,'KZT')} на2023–2025 годах и {delta(ci,'synth_kzt_halyk_D1','synth_kzt_no_oxr',JAN,'KZT')} в январской проверке2026 года. Но при D+2 исследовательский Brier ухудшается до0.184014, а январский — до0.241130. Практическая ценность банковского источника зависит от фактического времени публикации.

Сочетание OXR D+2 иHalyk D+1 даёт более высокий исследовательский Brier, чем один Halyk: {delta(ci,'synth_kzt_basis2010_halyk_H1O2','synth_kzt_halyk_D1',DEV,'KZT')}. Благоприятный отдельный результат этой комбинации в январе2026 года не использован для выбора модели. Нужны корректная сторона банковской котировки, подтверждённые времена доступности и проверка на новых данных; одно ретроспективное совпадение не доказывает пользу объединения источников.

**2026 год и неопределённость.** Он уже просматривался в прошлой работе и остаётся ретроспективной проверкой. Январские метрики рассчитаны на780 строках пяти валют; мартовские — на610. Для честного сравнения заморозок отдельно сохранены одинаковые122 даты с3марта по25августа2026 года: [общие мартовские даты](common_march_summary.csv), [парные интервалы](common_march_paired_intervals.csv). Это неполные шесть календарных месяцев. В мартовском варианте прежние веса нейросети сохранены, а обучение головы и двенадцатимесячная калибровка сдвинуты к1марта2026 года.

Все95% интервалы получены из10 000 парных выборок календарных месяцев, раздельно внутри каждого года. Валюты одной даты остаются вместе; средние случайного дня и число сигналов пересчитываются в каждой выборке. Интервалы условны на фиксированных обученных моделях и не учитывают весь исторический поиск гипотез. [Годовые валютные ячейки](cells.csv) показывают устойчивость и количество сигналов отдельно от агрегата.

**Проверки.** [Машинный статус](verification.json) содержит восстановление вероятностей и обеих политик всех85 сохранённых моделей, доказательство созревания меток, хэши источников, весов и кэшей, а также10 точных воспроизведений прежних моделей без OXR. Реальные преобразования OXR иHalyk проверены изменением будущих записей: прошлые признаки сохраняются, будущие контрольные признаки меняются. Старые V3/V4 файлы не изменялись. Все артефакты перечислены в [README](README.md) и [манифесте](MANIFEST.json).
'''
    if (OUT/'canonical/verification.json').exists():
        text+='''

**Дополнение после численного аудита.** Добавлены15 заранее описанных проверочных обучений: Synth +OXR basis2010, Small +OXR basis2010 иKZT-комбинация OXR D+2 сHalyk D+1, по всем пяти временным разбиениям. Для всех дат с1сентября2018 года числовые OXR-признаки заменены точными значениями представления систорией с17июня2018 года изтого же снимка. Вся настоящая более ранняя история2010–2018 годов иостальные признаки сохранены побитово. Это устраняет влияние накопленной погрешности скользящих расчётов изсравнения длинной икороткой истории.

Во всех15 обучениях вероятности, исходные вероятности иобе последовательности сигналов совпали сисходными результатами **точно**. Таким образом, обнаруженная погрешность не объясняет результаты этих трёх конфигураций. Для Synth разница Brier между канонической историей с2010 года иисторией с2018 года осталась +0.000019 [−0.000861;+0.000902] на исследовательских данных, −0.000172 на январской и−0.000720 на мартовской заморозке; все95% интервалы включают ноль. Прирост отранней истории не подтверждён.

Проверка выполнена после просмотра первоначальных результатов иобозначена как численная атрибуция, а не новая независимая проверка. Гиперпараметры иисходный выбор модели не менялись. Сохранены [протокол дополнения](canonical/protocol.json), [результаты](canonical/summary.csv), [парные интервалы](canonical/paired_intervals.csv) и[точное сравнение сисходными моделями](canonical/reproduction_to_original.json). Общий итог — **100 обученных голов,0 новых обучений нейросетей и0 новых нейросетевых прогнозов**; [объединённый статус проверок](final_verification.json).
'''
    # Keep Russian prose readable without altering numeric values or identifiers.
    import re
    text=re.sub(r'(?<=[А-Яа-яЁё])(?=\d)', ' ', text)
    text=re.sub(r'(?<=\d)(?=[А-Яа-яЁё])', ' ', text)
    text=text.replace('и14','и 14').replace('иfull','и full').replace('кKZT','к KZT').replace('иHalyk','и Halyk').replace('иD+3','и D+3').replace('с41.90','с 41.90').replace('до38.05','до 38.05').replace('HGB:120','HGB: 120').replace('54,454 строк','54 454 строки')
    for before,after in [('Synth +OXR','Synth + OXR'),('Small +OXR','Small + OXR'),('иKZT','и KZT'),('сHalyk','с Halyk'),('систорией','с историей'),('изтого','из того'),('иостальные','и остальные'),('изсравнения','из сравнения'),('икороткой','и короткой'),('иобе','и обе'),('сисходными','с исходными'),('иисторией','и историей'),('и−','и −'),('отранней','от ранней'),('иобозначена','и обозначена'),('иисходный','и исходный'),('и[','и ['),('голов,0','голов, 0')]:text=text.replace(before,after)
    (OUT/'REPORT.md').write_text(text);print('Report words:',len(text.split()))

if __name__=='__main__':main()
